//! A deliberately narrow validator for ArcForge's repository skills.
//! Frontmatter has exactly two single-line fields, not arbitrary YAML.

use std::fs;
use std::path::{Component, Path, PathBuf};

use crate::Result;

const NAMES: &[&str] = &[
    "arcforge-debug",
    "arcforge-verify",
    "arcforge-tdd",
    "arcforge-review",
    "arcforge-archive-safety",
    "arcforge-rust",
    "arcforge-ci",
    "arcforge-design-ux",
];
const MARKER: &str =
    "<!-- Generated by cargo xtask skills-sync; edit the canonical .agents skill. -->";

pub fn check(root: &Path) -> Result<()> {
    reconcile(root, false)?;
    println!(
        "All {} scoped skills and Claude entry points are valid and current.",
        NAMES.len()
    );
    Ok(())
}

pub fn sync(root: &Path) -> Result<()> {
    let changed = reconcile(root, true)?;
    println!("Updated {changed} generated Claude entry point(s).");
    Ok(())
}

fn reconcile(root: &Path, write: bool) -> Result<usize> {
    let root = root.canonicalize()?;
    for directory in [".agents/skills", ".claude/skills"] {
        let directory = owned_path(&root, directory)?;
        match fs::read_dir(&directory) {
            Ok(entries) => {
                let mut names = entries
                    .map(|entry| entry.map(|entry| entry.file_name()))
                    .collect::<std::io::Result<Vec<_>>>()?;
                names.sort();
                for name in names {
                    let name = name.to_string_lossy();
                    if name.starts_with("arcforge-") && !NAMES.contains(&name.as_ref()) {
                        return Err(format!("unexpected ArcForge skill at {}/{name}; inspect it manually; no files were removed", directory.display()).into());
                    }
                }
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => return Err(error.into()),
        }
    }
    let mut updates = Vec::new();
    for name in NAMES {
        let source = owned_path(&root, &format!(".agents/skills/{name}/SKILL.md"))?;
        let contents = fs::read_to_string(&source)
            .map_err(|error| format!("{}: {error}", source.display()))?;
        let (description, body) = parse(name, &contents)?;
        check_links(&root, &source, &body)?;
        let destination = owned_path(&root, &format!(".claude/skills/{name}/SKILL.md"))?;
        let expected = format!(
            "---\nname: {name}\ndescription: {}\n---\n\n{MARKER}\n\nRead [AGENTS.md](../../../AGENTS.md), then read the [canonical instructions](../../../.agents/skills/{name}/SKILL.md) in full before using this skill. Apply the repository's scoped trigger and verification rules.\n",
            serde_json::to_string(&description)?
        );
        let existing = match fs::read_to_string(&destination) {
            Ok(text) => Some(text),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => None,
            Err(error) => return Err(error.into()),
        };
        if existing.as_deref() == Some(expected.as_str()) {
            continue;
        }
        if write && existing.as_ref().is_some_and(|text| !text.contains(MARKER)) {
            return Err(format!(
                "refusing to overwrite an unrecognized file: {}",
                destination.display()
            )
            .into());
        }
        updates.push((destination, expected));
    }
    // Validate everything before making any changes. Read-only checks never sync.
    if !write && !updates.is_empty() {
        let paths = updates
            .iter()
            .map(|(path, _)| path.display().to_string())
            .collect::<Vec<_>>()
            .join("\n");
        return Err(format!("missing or stale Claude entry points:\n{paths}\nRun cargo xtask skills-sync, then review the generated changes.").into());
    }
    for (destination, contents) in &updates {
        fs::create_dir_all(destination.parent().ok_or("entry point has no parent")?)?;
        fs::write(destination, contents)?;
    }
    Ok(updates.len())
}

fn parse(name: &str, text: &str) -> Result<(String, String)> {
    let lines: Vec<_> = text.lines().collect();
    if lines.len() > 500 || lines.first() != Some(&"---") {
        return Err(
            format!("{name}: expected opening frontmatter; maximum 500 lines per skill").into(),
        );
    }
    let end = lines
        .iter()
        .skip(1)
        .position(|line| *line == "---")
        .map(|index| index + 1)
        .ok_or_else(|| format!("{name}: missing closing frontmatter delimiter"))?;
    if end != 3 {
        return Err(format!(
            "{name}: frontmatter must contain exactly name and description on separate lines"
        )
        .into());
    }
    let mut parsed_name = None;
    let mut description = None;
    for line in &lines[1..end] {
        let (key, value) = line
            .split_once(':')
            .ok_or_else(|| format!("{name}: malformed frontmatter field"))?;
        match key.trim() {
            "name" if parsed_name.is_none() => parsed_name = Some(value.trim()),
            "description" if description.is_none() => {
                description = Some(serde_json::from_str::<String>(value.trim()).map_err(
                    |error| {
                        format!(
                            "{name}: description must be a JSON-quoted single-line string: {error}"
                        )
                    },
                )?)
            }
            _ => {
                return Err(
                    format!("{name}: unexpected or repeated frontmatter key {key:?}").into(),
                );
            }
        }
    }
    if parsed_name != Some(name) {
        return Err(
            format!("{name}: frontmatter name must match its directory and be unquoted").into(),
        );
    }
    let description = description.ok_or_else(|| format!("{name}: missing description"))?;
    if description.trim().is_empty()
        || description.chars().count() > 1024
        || description.contains(['\n', '\r'])
    {
        return Err(format!("{name}: description must have 1–1024 characters on one line").into());
    }
    let body = lines[end + 1..].join("\n");
    if body.trim().is_empty() || body.split_whitespace().count() > 1000 {
        return Err(format!("{name}: body must have 1–1000 words").into());
    }
    Ok((description, body))
}

fn owned_path(root: &Path, relative: &str) -> Result<PathBuf> {
    let mut path = root.to_path_buf();
    for component in Path::new(relative).components() {
        let Component::Normal(component) = component else {
            return Err("skill path must remain inside the repository".into());
        };
        path.push(component);
        match fs::symlink_metadata(&path) {
            Ok(metadata) if metadata.file_type().is_symlink() => {
                return Err(format!(
                    "skill files and parent directories must not be symlinks: {}",
                    path.display()
                )
                .into());
            }
            Ok(_) => {}
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => return Err(error.into()),
        }
    }
    Ok(path)
}

fn check_links(root: &Path, source: &Path, body: &str) -> Result<()> {
    // Check simple inline Markdown destinations only; this is not a Markdown parser.
    for part in body.split("](").skip(1) {
        let Some((target, _)) = part.split_once(')') else {
            continue;
        };
        if target.starts_with('#')
            || target.contains("://")
            || target.starts_with("mailto:")
            || target.contains([' ', '\n', '(', '<', '>', '%', '\\'])
        {
            continue;
        }
        let path = target.split('#').next().unwrap_or_default();
        if path.is_empty() {
            continue;
        }
        let path = source.parent().ok_or("skill has no directory")?.join(path);
        let resolved = path.canonicalize().map_err(|error| {
            format!(
                "{}: broken local link {target:?}: {error}",
                source.display()
            )
        })?;
        if !resolved.starts_with(root) {
            return Err(format!(
                "{}: local link leaves the repository: {target:?}",
                source.display()
            )
            .into());
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::atomic::{AtomicU64, Ordering};
    use std::time::{SystemTime, UNIX_EPOCH};
    static NEXT: AtomicU64 = AtomicU64::new(0);

    struct Fixture(PathBuf);
    impl Fixture {
        fn new() -> Result<Self> {
            let nonce = SystemTime::now().duration_since(UNIX_EPOCH)?.as_nanos();
            let root = std::env::temp_dir().join(format!(
                "arcforge-skills-{}-{nonce}-{}",
                std::process::id(),
                NEXT.fetch_add(1, Ordering::Relaxed)
            ));
            fs::create_dir(&root)?;
            fs::write(root.join("AGENTS.md"), "Repository rules")?;
            for name in NAMES {
                let path = root.join(format!(".agents/skills/{name}"));
                fs::create_dir_all(&path)?;
                fs::write(
                    path.join("SKILL.md"),
                    format!(
                        "---\nname: {name}\ndescription: \"Use for a focused task.\"\n---\nFollow [rules](../../../AGENTS.md).\n"
                    ),
                )?;
            }
            Ok(Self(root.canonicalize()?))
        }
    }
    impl Drop for Fixture {
        fn drop(&mut self) {
            let _ = fs::remove_dir_all(&self.0);
        }
    }

    #[test]
    fn rejects_malformed_mismatched_and_oversized_skills() {
        for text in [
            "---\nname: other\ndescription: \"Use for debugging.\"\n---\nBody",
            "---\nname: arcforge-debug\ndescription: unquoted\n---\nBody",
            "---\nname: arcforge-debug\nname: arcforge-debug\n---\nBody",
            "---\nname: arcforge-debug\ndescription: \"\"\n---\nBody",
            "---\nname: arcforge-debug\ndescription: \"Use for debugging.\"\n---\n",
        ] {
            assert!(parse("arcforge-debug", text).is_err(), "{text}");
        }
        assert!(
            parse(
                "arcforge-debug",
                &format!(
                    "---\nname: arcforge-debug\ndescription: \"Use for debugging.\"\n---\n{}",
                    "word ".repeat(1001)
                )
            )
            .is_err()
        );
    }

    #[test]
    fn sync_roundtrip_is_idempotent_and_read_only_check_detects_drift() -> Result<()> {
        let fixture = Fixture::new()?;
        assert!(reconcile(&fixture.0, false).is_err());
        assert!(!fixture.0.join(".claude").exists());
        assert_eq!(reconcile(&fixture.0, true)?, NAMES.len());
        assert_eq!(reconcile(&fixture.0, false)?, 0);
        assert_eq!(reconcile(&fixture.0, true)?, 0);
        let wrapper = fixture.0.join(".claude/skills/arcforge-debug/SKILL.md");
        let expected = fs::read_to_string(&wrapper)?;
        fs::write(&wrapper, format!("{expected}\nStale text"))?;
        assert!(reconcile(&fixture.0, false).is_err());
        assert_eq!(reconcile(&fixture.0, true)?, 1);
        assert_eq!(fs::read_to_string(wrapper)?, expected);
        Ok(())
    }

    #[test]
    fn preserves_unrecognized_files_and_reports_stale_project_directories() -> Result<()> {
        let fixture = Fixture::new()?;
        let directory = fixture.0.join(".claude/skills/arcforge-review");
        fs::create_dir_all(&directory)?;
        fs::write(directory.join("SKILL.md"), "User-owned instructions")?;
        assert!(reconcile(&fixture.0, true).is_err());
        assert!(
            !fixture
                .0
                .join(".claude/skills/arcforge-debug/SKILL.md")
                .exists()
        );
        assert_eq!(
            fs::read_to_string(directory.join("SKILL.md"))?,
            "User-owned instructions"
        );
        fs::remove_dir_all(directory)?;
        let stale = fixture.0.join(".claude/skills/arcforge-old");
        fs::create_dir_all(&stale)?;
        assert!(reconcile(&fixture.0, true).is_err());
        assert!(stale.exists());
        Ok(())
    }

    #[test]
    fn rejects_dangling_links_and_path_escape() -> Result<()> {
        let fixture = Fixture::new()?;
        let source = fixture.0.join(".agents/skills/arcforge-debug/SKILL.md");
        assert!(check_links(&fixture.0, &source, "[missing](missing.md)").is_err());
        assert!(owned_path(&fixture.0, "../outside").is_err());
        check_links(
            &fixture.0,
            &source,
            "[rules](../../../AGENTS.md#rules) [web](https://example.test/path)",
        )?;
        Ok(())
    }
}
